   AND EXISTS(SELECT 1 FROM capacity_lease l WHERE l.mailbox_id=d.mailbox_id AND l.state='active' AND l.expires_at>clock_timestamp())`,[claim.mailbox_id,claim.kind,claim.owner_id,claim.generation]);
